//! Cross-implementation compatibility: the TetherWebUI TypeScript
//! exporter (src/plc/plcopen.ts) emits the same Roundtrip-mode TC6
//! this crate produces. The fixture was generated by that exporter;
//! importing it must recover the same fbd.v1 model losslessly.

use fbd_model::{BlockKind, IfaceKind, PortSel, VarRole};
use plcopen_io::import;

const TS_EXPORT: &str = include_str!("fixtures/ts_export_webui_demo.xml");

#[test]
fn webui_export_imports_losslessly() {
    let rep = import(TS_EXPORT).expect("webui-exported TC6 must import");
    let p = &rep.project;
    assert_eq!(p.project, "webui_demo");
    assert_eq!(p.pous.len(), 1);
    let pou = &p.pous[0];
    assert_eq!(pou.name, "MAIN");

    // interface: auto-emitted T1 instance decl lands in localVars
    let names: Vec<_> = pou.interface.iter().map(|v| v.name.as_str()).collect();
    assert!(names.contains(&"Start"));
    assert!(names.contains(&"Limit"));
    let limit = pou.interface.iter().find(|v| v.name == "Limit").unwrap();
    assert_eq!(limit.kind, IfaceKind::VarInput);
    assert_eq!(limit.init.as_deref(), Some("90"));

    let net = &pou.networks[0];
    assert_eq!(net.id, "net1");
    assert_eq!(net.blocks.len(), 4);

    let ton = net
        .blocks
        .iter()
        .find(|b| b.type_ref == "TON")
        .expect("TON block");
    assert_eq!(ton.kind, BlockKind::Fb);
    assert_eq!(ton.instance.as_deref(), Some("T1"));
    assert_eq!(ton.params.get("PT").map(String::as_str), Some("T#200ms"));

    let start = net.blocks.iter().find(|b| b.id == 1).unwrap();
    assert_eq!(start.role, Some(VarRole::In));
    assert_eq!(start.at.as_deref(), Some("%IX0.0"));
    assert_eq!(start.name.as_deref(), Some("Start"));

    // fan-out wire merged back via tether:wire ids; probe preserved
    let fanout = net.wires.iter().find(|w| w.src.block == 1).unwrap();
    assert_eq!(fanout.dsts.len(), 2);
    assert!(fanout.probe);
    assert!(fanout
        .dsts
        .iter()
        .any(|d| d.block == 2 && d.port == PortSel::Name("IN".into())));
    assert!(fanout
        .dsts
        .iter()
        .any(|d| d.block == 3 && d.port == PortSel::Index(0)));

    let q = net.wires.iter().find(|w| w.src.block == 2).unwrap();
    assert_eq!(q.src.port, PortSel::Name("Q".into()));

    // annotations + task table
    assert_eq!(net.comments[0].text, "heater control");
    assert_eq!(net.labels[0].name, "L1");
    assert_eq!(net.jumps[0].target, "L1");
    assert_eq!(net.returns.len(), 1);
    assert_eq!(p.tasks[0].name, "CYC");
    assert_eq!(p.tasks[0].programs, vec!["MAIN".to_string()]);
}

/// Reverse direction: Rust Roundtrip export -> write fixture for the
/// TS importer's test suite (kept in sync by hand — the fixture is
/// regenerated whenever this file's model changes).
#[test]
fn dump_rust_export_fixture() {
    if std::env::var("DUMP_RUST_EXPORT").is_err() {
        return;
    }
    let json = include_str!("fixtures/webui_demo.fbd.json");
    let p = fbd_model::from_json(json).unwrap();
    let (xml, losses) = plcopen_io::export(&p, plcopen_io::ExportMode::Roundtrip);
    assert!(losses.is_empty(), "{losses:?}");
    std::fs::write(
        concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/tests/fixtures/rust_export_webui_demo.xml"
        ),
        xml,
    )
    .unwrap();
}
